/* ============================================================
   Main app
   ============================================================ */
export default function ReactInterviewGuide() {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("All");
  const [page, setPage] = useState(1);
  const [openIds, setOpenIds] = useState<Set<number>>(() => new Set());
  const [filtersOpen, setFiltersOpen] = useState(false);
  const topRef = useRef<HTMLDivElement | null>(null);

  const categoryOrder = useMemo(() => {
    const seen: string[] = [];
    for (const e of RAW) if (!seen.includes(e.c)) seen.push(e.c);
    return seen;
  }, []);

  const categoryCounts = useMemo(() => {
    const m: Record<string, number> = {};
    for (const e of RAW) m[e.c] = (m[e.c] || 0) + 1;
    return m;
  }, []);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return RAW.filter((e) => {
      if (category !== "All" && e.c !== category) return false;
      if (!q) return true;
      return e.q.toLowerCase().includes(q) || e.a.toLowerCase().includes(q);
    });
  }, [query, category]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / PER_PAGE));

  useEffect(() => {
    setPage(1);
  }, [query, category]);

  useEffect(() => {
    if (page > totalPages) setPage(totalPages);
  }, [totalPages]); // eslint-disable-line

  const pageItems = filtered.slice((page - 1) * PER_PAGE, page * PER_PAGE);

  const goToPage = (updater: number | ((p: number) => number)) => {
    setPage(updater);
    topRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  const toggleCard = (id: number) => {
    setOpenIds((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  };

  const toggleAllOnPage = () => {
    setOpenIds((prev) => {
      const next = new Set(prev);
      const allOpen = pageItems.every((it) => next.has(it.id));
      pageItems.forEach((it) => {
        if (allOpen) {
          next.delete(it.id);
        } else {
          next.add(it.id);
        }
      });
      return next;
    });
  };

  const shownFrom = filtered.length === 0 ? 0 : (page - 1) * PER_PAGE + 1;
  const shownTo = Math.min(page * PER_PAGE, filtered.length);

  return (
    <div
      className="min-h-screen w-full"
      style={{ background: "#FAF9F6", fontFamily: "-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif" }}
    >
      <div ref={topRef} />

      <Navigation />

      <div className="mx-auto flex max-w-6xl gap-6 px-4 py-6 sm:px-6 lg:py-8 mt-50">
        {/* ===== Sidebar (desktop) ===== */}
        <aside className="hidden w-56 shrink-0 lg:block">
          <div className="sticky top-28 space-y-1">
            <p className="mb-2 px-2 font-mono text-[11px] uppercase tracking-wider" style={{ color: "#8B959B" }}>
              Topics
            </p>
            <CategoryButton
              label="All questions"
              count={RAW.length}
              active={category === "All"}
              onClick={() => setCategory("All")}
              color="#4B555C"
            />
            {categoryOrder.map((c) => (
              <CategoryButton
                key={c}
                label={c}
                count={categoryCounts[c]}
                active={category === c}
                onClick={() => setCategory(c)}
                color={catColor(c, categoryOrder)}
              />
            ))}
          </div>
        </aside>

        {/* ===== Mobile filter sheet ===== */}
        {filtersOpen && (
          <div className="fixed inset-0 z-40 lg:hidden">
            <div className="absolute inset-0 bg-black/40" onClick={() => setFiltersOpen(false)} />
            <div
              className="absolute inset-x-0 bottom-0 max-h-[75vh] overflow-y-auto rounded-t-2xl border-t p-4"
              style={{ background: "#FFFFFF", borderColor: "#E4E1D8" }}
            >
              <div className="mb-3 flex items-center justify-between">
                <p className="font-mono text-[11px] uppercase tracking-wider" style={{ color: "#8B959B" }}>
                  Topics
                </p>
                <button onClick={() => setFiltersOpen(false)}>
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} style={{ color: "#4B555C" }}>
                    <line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" />
                  </svg>
                </button>
              </div>
              <div className="space-y-1 pb-2">
                <CategoryButton
                  label="All questions"
                  count={RAW.length}
                  active={category === "All"}
                  onClick={() => { setCategory("All"); setFiltersOpen(false); }}
                  color="#4B555C"
                />
                {categoryOrder.map((c) => (
                  <CategoryButton
                    key={c}
                    label={c}
                    count={categoryCounts[c]}
                    active={category === c}
                    onClick={() => { setCategory(c); setFiltersOpen(false); }}
                    color={catColor(c, categoryOrder)}
                  />
                ))}
              </div>
            </div>
          </div>
        )}

        {/* ===== Main column ===== */}
        <main className="min-w-0 flex-1 pt-10">
          <div className="mb-4 flex flex-wrap items-center justify-between gap-2">
            <div className="flex items-center gap-2 font-mono text-[12px]" style={{ color: "#8B959B" }}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2}>
                <line x1="4" y1="9" x2="20" y2="9" /><line x1="4" y1="15" x2="20" y2="15" />
                <line x1="10" y1="3" x2="8" y2="21" /><line x1="16" y1="3" x2="14" y2="21" />
              </svg>
              {filtered.length} result{filtered.length === 1 ? "" : "s"}
              {category !== "All" && <span style={{ color: catColor(category, categoryOrder) }}>· {category}</span>}
            </div>
            <div className="mx-auto max-w-6xl px-4 pb-3.5 sm:px-6">
              <div
                className="flex items-center gap-2 rounded-xl border px-3.5"
                style={{ background: "#FFFFFF", borderColor: "#E4E1D8" }}
              >
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} style={{ color: "#8B959B" }}>
                  <circle cx="11" cy="11" r="8" /><line x1="21" y1="21" x2="16.65" y2="16.65" />
                </svg>
                <input
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                  placeholder="Search questions & answers…"
                  className="h-10 w-full bg-transparent text-[14px] outline-none placeholder:text-[#8B959B]"
                  style={{ color: "#1B2126" }}
                />
                {query && (
                  <button onClick={() => setQuery("")} aria-label="Clear search">
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} style={{ color: "#8B959B" }}>
                      <line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" />
                    </svg>
                  </button>
                )}
              </div>
            </div>
            <div className="flex text-[12.5px]">
              <button
                onClick={toggleAllOnPage}
                className="rounded-md px-2 py-1 font-medium transition hover:bg-gray-100"
                style={{ color: "#D16B3B" }}
              >
                {pageItems.length > 0 &&
                pageItems.every((it) => openIds.has(it.id))
                  ? "Collapse page"
                  : "Expand page"}
              </button>
            </div>
          </div>

          {pageItems.length === 0 ? (
            <div
              className="flex flex-col items-center justify-center rounded-2xl border py-20 text-center"
              style={{ borderColor: "#E4E1D8", color: "#8B959B" }}
            >
              <p className="mb-1 text-[15px] font-medium" style={{ color: "#1B2126" }}>No matches on the shelf</p>
              <p className="text-[13px]">Try a different search term or topic.</p>
            </div>
          ) : (
            <div className="space-y-5">
              {pageItems.map((item) => (
                <Card
                  key={item.id}
                  item={item}
                  isOpen={openIds.has(item.id)}
                  onToggle={() => toggleCard(item.id)}
                  accent={catColor(item.c, categoryOrder)}
                />
              ))}
            </div>
          )}

          {filtered.length > 0 && (
            <Pagination
              page={page}
              totalPages={totalPages}
              setPage={goToPage}
              total={filtered.length}
              shownFrom={shownFrom}
              shownTo={shownTo}
            />
          )}

          <div className="h-4" />
        </main>
      </div>
      <Footer />
    </div>
  );
}